/* Draws of a subpass read its depth as an input attachment (through the
 * depth copy) and write it, adding what they read to the color they also
 * read: the first must see the loaded depth (0.25), not what the pass
 * leaves (0.75), the second the first's (0.5). how: drawn as draw_via
 * does. */
static void depth_input_before_write(int how)
{
    enum { S = 8 }; /* (at 16 x 16 the old in-pass copy read the loaded depth, M4 Max) */
    VkAttachmentDescription a[2];
    VkAttachmentReference ro = { 0, VK_IMAGE_LAYOUT_GENERAL }, rds = { 1, VK_IMAGE_LAYOUT_GENERAL };
    VkAttachmentReference rin[2] = { { 0, VK_IMAGE_LAYOUT_GENERAL }, { 1, VK_IMAGE_LAYOUT_GENERAL } };
    VkSubpassDescription sp;
    VkSubpassDependency dep;
    VkRenderPassCreateInfo info;
    VkRenderPass rp = VK_NULL_HANDLE;
    struct img out = make_img(VK_FORMAT_R32G32B32A32_SFLOAT, S, S, 1, VK_SAMPLE_COUNT_1_BIT);
    struct img ds = make_img(VK_FORMAT_D32_SFLOAT_S8_UINT, S, S, 1, VK_SAMPLE_COUNT_1_BIT);
    struct buf got = make_buf(S * S * 16);
    VkImageView views[2] = { out.view, ds.view }, depth_view = aspect_view(&ds, VK_IMAGE_ASPECT_DEPTH_BIT);
    VkClearDepthStencilValue dv = { 0.25f, 0 };
    VkImageSubresourceRange range = { VK_IMAGE_ASPECT_DEPTH_BIT | VK_IMAGE_ASPECT_STENCIL_BIT, 0, 1, 0, 1 };
    VkDescriptorSetLayoutBinding binds[2];
    VkDescriptorSetLayoutCreateInfo sli;
    VkDescriptorSetLayout set_layout = VK_NULL_HANDLE;
    VkPushConstantRange pcr = { VK_SHADER_STAGE_VERTEX_BIT | VK_SHADER_STAGE_FRAGMENT_BIT, 0, sizeof(struct pc) };
    VkPipelineLayoutCreateInfo pli;
    VkPipelineLayout layout = VK_NULL_HANDLE;
    VkDescriptorPoolSize size = { VK_DESCRIPTOR_TYPE_INPUT_ATTACHMENT, 2 };
    VkDescriptorPoolCreateInfo dpi;
    VkDescriptorPool dpool = VK_NULL_HANDLE;
    VkDescriptorSetAllocateInfo dai;
    VkDescriptorSet set = VK_NULL_HANDLE;
    VkDescriptorImageInfo ii[2];
    VkWriteDescriptorSet w;
    VkMemoryBarrier mb;
    VkFramebuffer fb;
    VkClearValue clears[2];
    VkPipeline pipeline;
    struct pipe p;
    VkCommandBuffer cb;
    uint32_t i, bad = 0;

    memset(a, 0, sizeof(a));
    a[0].format = VK_FORMAT_R32G32B32A32_SFLOAT;
    a[1].format = VK_FORMAT_D32_SFLOAT_S8_UINT;
    memset(binds, 0, sizeof(binds));
    for (i = 0; i < 2; i++) {
        a[i].samples = VK_SAMPLE_COUNT_1_BIT;
        a[i].loadOp = i ? VK_ATTACHMENT_LOAD_OP_LOAD : VK_ATTACHMENT_LOAD_OP_CLEAR;
        a[i].stencilLoadOp = VK_ATTACHMENT_LOAD_OP_LOAD;
        a[i].storeOp = a[i].stencilStoreOp = VK_ATTACHMENT_STORE_OP_STORE;
        a[i].initialLayout = a[i].finalLayout = VK_IMAGE_LAYOUT_GENERAL;
        binds[i].binding = i;
        binds[i].descriptorType = VK_DESCRIPTOR_TYPE_INPUT_ATTACHMENT;
        binds[i].descriptorCount = 1;
        binds[i].stageFlags = VK_SHADER_STAGE_FRAGMENT_BIT;
        ii[i].sampler = VK_NULL_HANDLE;
        ii[i].imageView = i ? depth_view : out.view;
        ii[i].imageLayout = VK_IMAGE_LAYOUT_GENERAL;
    }
    memset(&sp, 0, sizeof(sp));
    sp.pipelineBindPoint = VK_PIPELINE_BIND_POINT_GRAPHICS;
    sp.colorAttachmentCount = 1;
    sp.pColorAttachments = &ro;
    sp.pDepthStencilAttachment = &rds;
    sp.inputAttachmentCount = 2;
    sp.pInputAttachments = rin;
    memset(&dep, 0, sizeof(dep));
    dep.srcSubpass = dep.dstSubpass = 0;
    dep.srcStageMask = dep.dstStageMask = VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT |
                                          VK_PIPELINE_STAGE_EARLY_FRAGMENT_TESTS_BIT |
                                          VK_PIPELINE_STAGE_LATE_FRAGMENT_TESTS_BIT |
                                          VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT;
    dep.srcAccessMask = dep.dstAccessMask = VK_ACCESS_INPUT_ATTACHMENT_READ_BIT |
                                            VK_ACCESS_DEPTH_STENCIL_ATTACHMENT_WRITE_BIT |
                                            VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT;
    dep.dependencyFlags = VK_DEPENDENCY_BY_REGION_BIT;
    memset(&info, 0, sizeof(info));
    info.sType = VK_STRUCTURE_TYPE_RENDER_PASS_CREATE_INFO;
    info.attachmentCount = 2;
    info.pAttachments = a;
    info.subpassCount = 1;
    info.pSubpasses = &sp;
    info.dependencyCount = 1;
    info.pDependencies = &dep;
    CHECK_VK(vkCreateRenderPass(device, &info, NULL, &rp), VK_SUCCESS);
    fb = make_fb(rp, views, 2, S, S, 1);
    memset(&sli, 0, sizeof(sli));
    sli.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO;
    sli.bindingCount = 2;
    sli.pBindings = binds;
    CHECK_VK(vkCreateDescriptorSetLayout(device, &sli, NULL, &set_layout), VK_SUCCESS);
    memset(&pli, 0, sizeof(pli));
    pli.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    pli.setLayoutCount = 1;
    pli.pSetLayouts = &set_layout;
    pli.pushConstantRangeCount = 1;
    pli.pPushConstantRanges = &pcr;
    CHECK_VK(vkCreatePipelineLayout(device, &pli, NULL, &layout), VK_SUCCESS);
    memset(&dpi, 0, sizeof(dpi));
    dpi.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO;
    dpi.maxSets = 1;
    dpi.poolSizeCount = 1;
    dpi.pPoolSizes = &size;
    CHECK_VK(vkCreateDescriptorPool(device, &dpi, NULL, &dpool), VK_SUCCESS);
    memset(&dai, 0, sizeof(dai));
    dai.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO;
    dai.descriptorPool = dpool;
    dai.descriptorSetCount = 1;
    dai.pSetLayouts = &set_layout;
    CHECK_VK(vkAllocateDescriptorSets(device, &dai, &set), VK_SUCCESS);
    memset(&w, 0, sizeof(w));
    w.sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;
    w.dstSet = set;
    w.descriptorCount = 2;
    w.descriptorType = VK_DESCRIPTOR_TYPE_INPUT_ATTACHMENT;
    w.pImageInfo = ii;
    vkUpdateDescriptorSets(device, 1, &w, 0, NULL);
    pipe_init(&p, spv_rect_vs, sizeof(spv_rect_vs), spv_add_depth_fs, sizeof(spv_add_depth_fs));
    p.layout = layout;
    p.rp = rp;
    p.has_ds = true;
    memset(&p.ds, 0, sizeof(p.ds));
    p.ds.depthTestEnable = p.ds.depthWriteEnable = VK_TRUE;
    p.ds.depthCompareOp = VK_COMPARE_OP_ALWAYS;
    pipeline = make_pipe(&p);
    REQUIRE(pipeline);
    memset(&mb, 0, sizeof(mb));
    mb.sType = VK_STRUCTURE_TYPE_MEMORY_BARRIER;
    mb.srcAccessMask = mb.dstAccessMask = dep.srcAccessMask;
    memset(clears, 0, sizeof(clears));
    cb = begin_cmd();
    vkCmdClearDepthStencilImage(cb, ds.image, VK_IMAGE_LAYOUT_GENERAL, &dv, 1, &range);
    barrier(cb);
    begin_pass(cb, rp, fb, 0, 0, S, S, clears, 2);
    vkCmdBindPipeline(cb, VK_PIPELINE_BIND_POINT_GRAPHICS, pipeline);
    vkCmdBindDescriptorSets(cb, VK_PIPELINE_BIND_POINT_GRAPHICS, layout, 0, 1, &set, 0, NULL);
    for (i = 0; i < 2; i++) {
        if (i)
            vkCmdPipelineBarrier(cb, dep.srcStageMask, dep.dstStageMask, VK_DEPENDENCY_BY_REGION_BIT, 1, &mb, 0, NULL,
                                 0, NULL);
        vkCmdPushConstants(cb, layout, VK_SHADER_STAGE_VERTEX_BIT | VK_SHADER_STAGE_FRAGMENT_BIT, 0, sizeof(struct pc),
                           &(struct pc){ { -1, -1, 1, 1 }, { 0, 0, 0, 0 }, i ? 0.75f : 0.5f, 0, 0, 0 });
        via = how;
        draw_via(cb, 4, 0);
    }
    vkCmdEndRenderPass(cb);
    download(cb, &out, 0, VK_IMAGE_ASPECT_COLOR_BIT, &got);
    submit(cb);
    for (i = 0; i < S * S; i++) {
        const float *t = (const float *)got.data + 4 * i;
        if ((t[0] != 0.75f || t[1] != 0.0f || t[3] != 2.0f) && bad++ < 4)
            fprintf(stderr, "depth input before write: texel %u is %g %g %g %g\n", i, t[0], t[1], t[2], t[3]);
    }
    CHECK(bad == 0);
    via_end();
    vkDestroyPipeline(device, pipeline, NULL);
    vkDestroyDescriptorPool(device, dpool, NULL);
    vkDestroyPipelineLayout(device, layout, NULL);
    vkDestroyDescriptorSetLayout(device, set_layout, NULL);
    vkDestroyImageView(device, depth_view, NULL);
    vkDestroyFramebuffer(device, fb, NULL);
    vkDestroyRenderPass(device, rp, NULL);
    free_buf(&got);
    free_img(&out);
    free_img(&ds);
}

static void test_depth_input_before_write(void)
{
    depth_input_before_write(0);
}

/* As count draws and long multi-draws, in a pass with the depth copy. */
static void test_depth_input_indirect(void)
{
    depth_input_before_write(1);
    depth_input_before_write(2);
}

/* Depth bounds (depthBounds), with one and four samples: the scene's
 * sloped triangle over depth 0.5, then a full-screen draw at depth 0.95
 * with static bounds [0.3, 0.6] writing red and its depth, then one at 0.05
 * without a fragment shader with dynamic bounds [0.9, 1.0]: a sample passes
 * where the depth the earlier draws left lies in the bounds. The expected
 * values come from the scene drawn alone. how: the bounded draws drawn as
 * draw_via does. */
static void depth_bounds_case(VkSampleCountFlagBits samples, int how)
{
    static const VkDynamicState dyn[2] = { VK_DYNAMIC_STATE_DEPTH_BOUNDS, VK_DYNAMIC_STATE_DEPTH_BOUNDS_TEST_ENABLE };
    static const float quads[] = { /* full screen at 0.95, then at 0.05 */
        -1.0f, -1.0f, 0.95f, 1.0f, -1.0f, 0.95f, -1.0f, 1.0f, 0.95f, 1.0f, -1.0f, 0.95f, 1.0f, 1.0f, 0.95f, -1.0f, 1.0f, 0.95f,
        -1.0f, -1.0f, 0.05f, 1.0f, -1.0f, 0.05f, -1.0f, 1.0f, 0.05f, 1.0f, -1.0f, 0.05f, 1.0f, 1.0f, 0.05f, -1.0f, 1.0f, 0.05f,
    };
    VkFormat format = VK_FORMAT_D32_SFLOAT_S8_UINT;
    struct img out = make_img(VK_FORMAT_R32G32B32A32_SFLOAT, W, H, 1, samples);
    struct img ds = make_img(format, W, H, 1, samples);
    struct buf got = make_buf(W * H * 16), depth = make_buf(W * H * 4), qb = make_buf(sizeof(quads));
    float before[4][W * H], after_depth[4][W * H], after_red[4][W * H];
    uint32_t k, i, n = (uint32_t)samples;
    struct ds_setup s;
    struct pipe p;
    VkPipeline scene[3], bounded, dynamic;
    VkCommandBuffer cb;
    VkDeviceSize zero = 0;
    struct pc pc;
    int bad = 0, passed[2] = { 0, 0 };
    int pass;

    REQUIRE(features.depthBounds);
    ds_setup_init(&s, &ds);
    memcpy(qb.data, quads, sizeof(quads));
    pipe_init(&p, spv_pos3_vs, sizeof(spv_pos3_vs), NULL, 0);
    p.color_formats[0] = VK_FORMAT_R32G32B32A32_SFLOAT;
    p.depth_format = p.stencil_format = format;
    p.samples = samples;
    ds_scene_pipelines(&s, &p, false, scene);
    p.topology = VK_PRIMITIVE_TOPOLOGY_TRIANGLE_LIST;
    p.vertex = &s.vi;
    p.has_ds = true;
    memset(&p.ds, 0, sizeof(p.ds));
    p.ds.depthTestEnable = p.ds.depthWriteEnable = VK_TRUE;
    p.ds.depthCompareOp = VK_COMPARE_OP_ALWAYS;
    p.ds.depthBoundsTestEnable = VK_TRUE;
    p.ds.minDepthBounds = 0.3f;
    p.ds.maxDepthBounds = 0.6f;
    p.fs = spv_rect_fs;
    p.fs_size = sizeof(spv_rect_fs);
    bounded = make_pipe(&p);
    p.fs = NULL;
    p.fs_size = 0;
    p.ds.depthBoundsTestEnable = VK_FALSE;
    p.dynamic = dyn;
    p.dynamic_count = 2;
    dynamic = make_pipe(&p);
    REQUIRE(scene[0] && bounded && dynamic);
    for (pass = 0; pass < 2; pass++) { /* the scene alone, then with the bounded draws */
        cb = begin_cmd();
        begin_rendering(cb, &out, 1, (const float[4]){ 0, 0, 0, 0 }, &ds); /* depth cleared to 1 */
        vkCmdBindVertexBuffers(cb, 0, 1, &s.vb.buffer, &zero);
        vkCmdBindPipeline(cb, VK_PIPELINE_BIND_POINT_GRAPHICS, scene[0]);
        vkCmdDraw(cb, 6, 1, 0, 0); /* 0.5 */
        vkCmdDraw(cb, 3, 1, 6, 0); /* the sloped triangle (ALWAYS) */
        if (pass) {
            vkCmdBindVertexBuffers(cb, 0, 1, &qb.buffer, &zero);
            vkCmdBindPipeline(cb, VK_PIPELINE_BIND_POINT_GRAPHICS, bounded);
            memset(&pc, 0, sizeof(pc));
            pc.color[0] = pc.color[3] = 1.0f;
            vkCmdPushConstants(cb, pc_layout, VK_SHADER_STAGE_VERTEX_BIT | VK_SHADER_STAGE_FRAGMENT_BIT, 0, sizeof(pc),
                               &pc);
            via = how;
            draw_via(cb, 6, 0);
            vkCmdBindPipeline(cb, VK_PIPELINE_BIND_POINT_GRAPHICS, dynamic);
            vkCmdSetDepthBoundsTestEnable(cb, VK_TRUE);
            vkCmdSetDepthBounds(cb, 0.9f, 1.0f);
            draw_via(cb, 6, 6);
        }
        vkCmdEndRendering(cb);
        if (n == 1) {
            download(cb, &out, 0, VK_IMAGE_ASPECT_COLOR_BIT, &got);
            download(cb, &ds, 0, VK_IMAGE_ASPECT_DEPTH_BIT, &depth);
        }
        submit(cb);
        for (k = 0; k < n; k++) {
            const float *f = (const float *)got.data;
            if (n > 1)
                ms_fetch_sample(&s, &out, &ds, k, &got);
            for (i = 0; i < W * H; i++) {
                float d = n > 1 ? f[4 * i + 2] : ((const float *)depth.data)[i];
                if (pass)
                    after_depth[k][i] = d, after_red[k][i] = f[4 * i];
                else
                    before[k][i] = d;
            }
        }
    }
    for (k = 0; k < n; k++)
        for (i = 0; i < W * H; i++) {
            float d = before[k][i], red = 0.0f;
            if (d >= 0.3f && d <= 0.6f)
                d = 0.95f, red = 1.0f, passed[0]++;
            if (d >= 0.9f && d <= 1.0f)
                d = 0.05f, passed[1]++;
            if (after_depth[k][i] != d || after_red[k][i] != red) {
                if (bad < 4)
                    fprintf(stderr, "depth bounds %ux: sample %u of (%u, %u): depth %g red %g, expected %g %g (before %g)\n",
                            n, k, i % W, i / W, after_depth[k][i], after_red[k][i], d, red, before[k][i]);
                bad++;
            }
        }
    CHECK(bad == 0);
    CHECK(passed[0] > 0 && passed[0] < (int)(W * H * n) && passed[1] >= passed[0]); /* (the bounds decided) */
    via_end();
    vkDestroyPipeline(device, bounded, NULL);
    vkDestroyPipeline(device, dynamic, NULL);
    for (k = 0; k < 3; k++)
        vkDestroyPipeline(device, scene[k], NULL);
    ds_setup_fini(&s);
    free_buf(&got);
    free_buf(&depth);
    free_buf(&qb);
    free_img(&out);
    free_img(&ds);
}

static void test_depth_bounds(void)
{
    depth_bounds_case(VK_SAMPLE_COUNT_1_BIT, 0);
    depth_bounds_case(VK_SAMPLE_COUNT_4_BIT, 0);
}

/* The bounded draws as a count draw and a long multi-draw: in a pass with
 * the depth copy, their records drawn one by one (pvk_prepass_later). */
static void test_depth_bounds_indirect(void)
{
    depth_bounds_case(VK_SAMPLE_COUNT_1_BIT, 1);
    depth_bounds_case(VK_SAMPLE_COUNT_4_BIT, 2);
}

/* A pipeline leaving the depth bounds test dynamic: the left half drawn red
 * at depth 0.5 with the test off, then (later passes) everything blue at 0.9
 * with bounds [0.4, 0.6] on, which passes where the first draw wrote. A pass
 * keeps its depth copy only when a draw tests the bounds: the earlier draw
 * must write the copy too, and a pass that never tests them draws alike.
 * The third pass begins in a secondary command buffer, which draws the left
 * half and suspends it; the primary resumes it to test the bounds. */
static void test_depth_bounds_later(void)
{
    static const VkDynamicState dyn[2] = { VK_DYNAMIC_STATE_DEPTH_BOUNDS, VK_DYNAMIC_STATE_DEPTH_BOUNDS_TEST_ENABLE };
    static const float black[4] = { 0, 0, 0, 1 };
    struct img target = make_img(VK_FORMAT_R8G8B8A8_UNORM, W, H, 1, VK_SAMPLE_COUNT_1_BIT);
    struct img ds = make_img(VK_FORMAT_D32_SFLOAT, W, H, 1, VK_SAMPLE_COUNT_1_BIT);
    struct buf out = make_buf(W * H * 4), depth = make_buf(W * H * 4);
    VkRenderingAttachmentInfo att[2];
    VkRenderingInfo info;
    VkCommandBufferAllocateInfo alloc;
    VkCommandBufferInheritanceInfo inh;
    VkCommandBufferBeginInfo begin;
    struct pipe p;
    VkPipeline pipeline;
    VkCommandBuffer cb, sec = VK_NULL_HANDLE;
    uint32_t x, y;
    int pass, bad = 0;

    REQUIRE(features.depthBounds);
    pipe_init(&p, spv_rect_vs, sizeof(spv_rect_vs), spv_rect_fs, sizeof(spv_rect_fs));
    p.depth_format = VK_FORMAT_D32_SFLOAT;
    p.has_ds = true;
    p.ds.depthTestEnable = p.ds.depthWriteEnable = VK_TRUE;
    p.ds.depthCompareOp = VK_COMPARE_OP_ALWAYS;
    p.dynamic = dyn;
    p.dynamic_count = 2;
    pipeline = make_pipe(&p);
    REQUIRE(pipeline);
    memset(att, 0, sizeof(att)); /* (begin_rendering's, for the third pass) */
    for (x = 0; x < 2; x++) {
        att[x].sType = VK_STRUCTURE_TYPE_RENDERING_ATTACHMENT_INFO;
        att[x].imageView = x ? ds.view : target.view;
        att[x].imageLayout = VK_IMAGE_LAYOUT_GENERAL;
        att[x].loadOp = VK_ATTACHMENT_LOAD_OP_CLEAR;
        att[x].storeOp = VK_ATTACHMENT_STORE_OP_STORE;
    }
    memcpy(att[0].clearValue.color.float32, black, sizeof(black));
    att[1].clearValue.depthStencil.depth = 1.0f;
    memset(&info, 0, sizeof(info));
    info.sType = VK_STRUCTURE_TYPE_RENDERING_INFO;
    info.renderArea.extent.width = W;
    info.renderArea.extent.height = H;
    info.layerCount = 1;
    info.colorAttachmentCount = 1;
    info.pColorAttachments = &att[0];
    info.pDepthAttachment = &att[1];
    memset(&alloc, 0, sizeof(alloc));
    alloc.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO;
    alloc.commandPool = cmd_pool;
    alloc.level = VK_COMMAND_BUFFER_LEVEL_SECONDARY;
    alloc.commandBufferCount = 1;
    memset(&inh, 0, sizeof(inh));
    inh.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_INHERITANCE_INFO;
    memset(&begin, 0, sizeof(begin));
    begin.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO;
    begin.flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;
    begin.pInheritanceInfo = &inh;
    for (pass = 0; pass < 3; pass++) {
        VkCommandBuffer rec = cb = begin_cmd();
        if (pass < 2) {
            begin_rendering(cb, &target, 1, black, &ds); /* depth cleared to 1 */
        } else {
            vkAllocateCommandBuffers(device, &alloc, &sec);
            vkBeginCommandBuffer(sec, &begin);
            rec = sec;
            info.flags = VK_RENDERING_SUSPENDING_BIT;
            vkCmdBeginRendering(sec, &info);
        }
        vkCmdBindPipeline(rec, VK_PIPELINE_BIND_POINT_GRAPHICS, pipeline);
        vkCmdSetDepthBoundsTestEnable(rec, VK_FALSE);
        vkCmdSetDepthBounds(rec, 0.4f, 0.6f);
        rect(rec, -1, -1, 0, 1, 1, 0, 0, 1, 0.5f);
        if (pass == 2) {
            vkCmdEndRendering(sec);
            vkEndCommandBuffer(sec);
            vkCmdExecuteCommands(cb, 1, &sec);
            info.flags = VK_RENDERING_RESUMING_BIT;
            vkCmdBeginRendering(cb, &info);
            vkCmdBindPipeline(cb, VK_PIPELINE_BIND_POINT_GRAPHICS, pipeline);
            vkCmdSetDepthBounds(cb, 0.4f, 0.6f);
        }
        if (pass) {
            vkCmdSetDepthBoundsTestEnable(cb, VK_TRUE);
            rect(cb, -1, -1, 1, 1, 0, 0, 1, 1, 0.9f);
        }
        vkCmdEndRendering(cb);
        download(cb, &target, 0, VK_IMAGE_ASPECT_COLOR_BIT, &out);
        download(cb, &ds, 0, VK_IMAGE_ASPECT_DEPTH_BIT, &depth);
        submit(cb);
        if (pass == 2)
            vkFreeCommandBuffers(device, cmd_pool, 1, &sec);
        for (y = 0; y < H; y++)
            for (x = 0; x < W; x++) {
                bool left = x < W / 2;
                uint32_t want = left ? (pass ? BLUE : RED) : BLACK;
                float d = ((const float *)depth.data)[y * W + x], want_d = left ? (pass ? 0.9f : 0.5f) : 1.0f;
                if ((px(&out, x, y) != want || d != want_d) && bad++ < 4)
                    fprintf(stderr, "depth bounds turned on later, pass %d: pixel (%u, %u) is %08x depth %g, "
                            "expected %08x %g\n", pass, x, y, px(&out, x, y), d, want, want_d);
            }
    }
    CHECK(bad == 0);
    vkDestroyPipeline(device, pipeline, NULL);
    free_buf(&out);
    free_buf(&depth);
    free_img(&target);
    free_img(&ds);
}

static void test_ds_subpasses(void)
{
    ds_subpass_case(VK_FORMAT_D32_SFLOAT_S8_UINT, VK_SAMPLE_COUNT_1_BIT, true, false, false);
    ds_subpass_case(VK_FORMAT_D32_SFLOAT_S8_UINT, VK_SAMPLE_COUNT_1_BIT, false, false, false);
    ds_subpass_case(VK_FORMAT_D16_UNORM, VK_SAMPLE_COUNT_1_BIT, true, false, false);
    ds_subpass_case(VK_FORMAT_D32_SFLOAT_S8_UINT, VK_SAMPLE_COUNT_1_BIT, true, true, false);
    ds_subpass_case(VK_FORMAT_D32_SFLOAT_S8_UINT, VK_SAMPLE_COUNT_4_BIT, true, false, false);
    ds_subpass_case(VK_FORMAT_D32_SFLOAT_S8_UINT, VK_SAMPLE_COUNT_4_BIT, true, true, false);
    ds_subpass_case(VK_FORMAT_D32_SFLOAT_S8_UINT, VK_SAMPLE_COUNT_4_BIT, false, false, false); /* read from textures */
    ds_subpass_case(VK_FORMAT_D32_SFLOAT_S8_UINT, VK_SAMPLE_COUNT_4_BIT, false, true, false);
    ds_subpass_case(VK_FORMAT_D32_SFLOAT_S8_UINT, VK_SAMPLE_COUNT_1_BIT, true, false, true);
}

